(function(){'use strict';
const copy=x=>JSON.parse(JSON.stringify(x)),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allowed=['structure','bounds','search','insert','neighbors','successor','delete','traversal','reconstruct','rank','select','range','multiplicity','cost','orders','rotation','random'];
function validate(raw){const s=copy(raw);if(!allowed.includes(s.operation))throw Error('Choose a declared tree operation.');if(!Array.isArray(s.keys)||s.keys.length<1||s.keys.length>9||s.keys.some(x=>!Number.isInteger(x)||Math.abs(x)>999)||new Set(s.keys).size!==s.keys.length)throw Error('Use one through nine distinct integer keys between -999 and 999.');for(const k of['q','a','b'])if(s[k]!==undefined&&(!Number.isInteger(s[k])||Math.abs(s[k])>999))throw Error('Query and interval bounds must be integers between -999 and 999.');if(['search','neighbors','successor','delete','rank','select'].includes(s.operation)&&s.q===undefined)throw Error('A query is required.');if(s.operation==='select'&&(s.q<0||s.q>=s.keys.length))throw Error('Select uses a zero-based rank smaller than the node count.');if(s.operation==='range'&&(s.a===undefined||s.b===undefined||s.a>s.b))throw Error('Use a nonreversed interval with both endpoints.');if(s.operation==='successor'&&!s.keys.includes(s.q))throw Error('Successor demonstration requires a stored key.');if(['orders'].includes(s.operation)&&s.keys.length>7)throw Error('Full producing-order enumeration is limited to seven keys.');if(s.operation==='random'&&s.keys.length!==3)throw Error('The exact shape distribution uses three distinct keys.');return s;}
function node(k,c=1){return{key:k,count:c,left:null,right:null};}function put(t,k){if(!t)return node(k);if(k<t.key)t.left=put(t.left,k);else if(k>t.key)t.right=put(t.right,k);return t;}function build(a){let t=null;for(const k of a)t=put(t,k);return t;}function list(t,order='inorder'){if(!t)return[];return order==='preorder'?[t.key,...list(t.left,order),...list(t.right,order)]:order==='postorder'?[...list(t.left,order),...list(t.right,order),t.key]:[...list(t.left,order),t.key,...list(t.right,order)];}function size(t){return t?1+size(t.left)+size(t.right):0;}function mass(t){return t?t.count+mass(t.left)+mass(t.right):0;}function height(t){return t?1+Math.max(height(t.left),height(t.right)):-1;}function find(t,k){while(t&&t.key!==k)t=k<t.key?t.left:t.right;return t;}function min(t){while(t.left)t=t.left;return t;}function removeMin(t){if(!t.left)return t.right;t.left=removeMin(t.left);return t;}function erase(t,k){if(!t)return null;if(k<t.key)t.left=erase(t.left,k);else if(k>t.key)t.right=erase(t.right,k);else{if(!t.left)return t.right;if(!t.right)return t.left;const u=min(t.right);t.key=u.key;t.count=u.count;t.right=removeMin(t.right);}return t;}
function valid(t,lo=-Infinity,hi=Infinity){return!t||(lo<t.key&&t.key<hi&&valid(t.left,lo,t.key)&&valid(t.right,t.key,hi));}function path(t,q){const a=[];while(t){a.push(t.key);if(q===t.key)break;t=q<t.key?t.left:t.right;}return a;}function stats(t,d=0){if(!t)return{n:0,I:0,E:d,gaps:[d]};const a=stats(t.left,d+1),b=stats(t.right,d+1);return{n:1+a.n+b.n,I:d+a.I+b.I,E:a.E+b.E,gaps:a.gaps.concat(b.gaps)};}
function permutations(a){if(!a.length)return[[]];return a.flatMap((x,i)=>permutations(a.filter((_,j)=>j!==i)).map(z=>[x,...z]));}function shape(t){return t?[shape(t.left),shape(t.right)]:null;}function label(t){return t?[t.key,label(t.left),label(t.right)]:null;}
function evaluate(raw){const s=validate(raw);let t=build(s.keys),states=[];const add=(action,why,extra={})=>states.push({tree:copy(t),action,why,active:[],...copy(extra)});let result={};
if(s.operation==='structure'){const r=stats(t);result={...r,height:height(t),inorder:list(t)};add('Inspect the owned child links and depth levels.','Every actual node has two child positions; n minus one are nonnull edges.',{lines:['Actual nodes: '+r.n,'Null gaps: '+r.gaps.length,'Edge height: '+height(t)]});}
else if(s.operation==='bounds'){t=node(20);t.left=node(10);t.right=node(30);t.left.right=node(25);for(const[k,lo,hi]of[[20,null,null],[10,null,20],[25,10,20]])add('Check key '+k+' against its inherited interval.','Every ancestor bound remains active after a later turn.',{active:[k],bad:k===25,lines:['Allowed: '+(lo??'-infinity')+' < key < '+(hi??'infinity'),k===25?'25 violates the upper bound 20.':'This node satisfies its bounds.']});result={valid:false,witness:25};}
else if(s.operation==='insert'){t=null;add('Start with the empty dictionary.','The first key changes the outer root link.',{lines:['Inserted keys: 0','Key comparisons: 0'],comparisons:0});let total=0;for(const k of s.keys){const route=path(t,k);total+=route.length;t=put(t,k);add('Insert '+k+' at the failed-search null link.','The new node lies inside every ancestor bound.',{active:[k],route,comparisons:total,lines:['New key: '+k,'Path: '+(route.join(' -> ')||'empty root'),'Total comparisons: '+total]});}result={preorder:list(t,'preorder'),comparisons:total,height:height(t)};}
else if(['search','neighbors'].includes(s.operation)){let v=t,lo=null,hi=null,c=0;while(v){c++;if(s.q<v.key)hi=v.key;else if(s.q>v.key)lo=v.key;add('Compare query '+s.q+' with key '+v.key+'.','Discard only the subtree excluded by the global ordering invariant.',{active:[v.key],comparisons:c,lines:['Query: '+s.q,'Comparisons: '+c,'Lower candidate: '+(lo??'absent'),'Upper candidate: '+(hi??'absent')]});if(s.q===v.key)break;v=s.q<v.key?v.left:v.right;}const found=Boolean(v);if(!found)add('Reach a null link and certify absence.','Every remaining possible occurrence has been excluded.',{lines:['Query '+s.q+' is absent.','Floor: '+(lo??'absent'),'Ceiling: '+(hi??'absent'),'Comparisons: '+c],comparisons:c});result={found,comparisons:c,floor:found?s.q:lo,ceiling:found?s.q:hi};}
else if(s.operation==='successor'){const u=find(t,s.q),route=path(t,s.q);if(u.right){let v=u.right;while(v){add('Follow the right subtree left spine at '+v.key+'.','Its minimum is the smallest key strictly above the query.',{active:[v.key],lines:['Stored query: '+s.q,'Candidate: '+v.key]});if(!v.left){result={successor:v.key};break;}v=v.left;}}else{let cur=s.q;result={successor:null};for(let i=route.length-2;i>=0;i--){const p=route[i],fromLeft=cur<p;add('Climb from '+cur+' to parent '+p+'.','An ancestor reached from the left is the first larger ancestor.',{active:[cur,p],lines:['Arrive from '+(fromLeft?'left':'right'),'Decision: '+(fromLeft?'stop; successor found':'continue climbing')]});if(fromLeft){result={successor:p};break;}cur=p;}if(result.successor===null)add('The upward route reaches above the root.','No larger stored key exists.',{lines:['The query is the maximum.','Successor: absent']});}}
else if(s.operation==='delete'){const target=find(t,s.q);add('Locate key '+s.q+' before changing links.','Absent deletion leaves the tree unchanged.',{active:target?[s.q]:[],lines:['Target: '+s.q,'Present: '+Boolean(target)]});if(target){if(target.left&&target.right){const u=min(target.right);add('Identify successor '+u.key+' and its surviving right child.','The successor has no left child; its right subtree must remain reachable.',{active:[s.q,u.key],lines:['Successor: '+u.key,'Successor right child: '+(u.right?.key??'null'),'Transfer key and value together.']});}else add('Replace the target owning link by its sole child or null.','The entire surviving subtree keeps the inherited ancestor bounds.',{active:[s.q],lines:['Replacement: '+(target.left?.key??target.right?.key??'null'),'Update the outer root if necessary.']});t=erase(t,s.q);add('Complete association copying and reconnect all surviving children.','Exactly the target key is removed; all other entries remain.',{active:[],lines:['Remaining nodes: '+size(t),'Order check: '+valid(t)]});}result={preorder:list(t,'preorder'),inorder:list(t),size:size(t),height:height(t)};}
else if(s.operation==='traversal'){const out=[];const walk=v=>{if(!v)return;walk(v.left);out.push(v.key);add('Emit '+v.key+' after its left subtree.','The inherited strict order makes inorder increasing.',{active:[v.key],emitted:copy(out),lines:['Emitted keys: '+out.length,'All earlier emissions are smaller.']});walk(v.right);};walk(t);result={inorder:out};}
else if(s.operation==='reconstruct'){t=null;let i=0;const parse=(lo,hi)=>{if(i===s.keys.length||!(lo<s.keys[i]&&s.keys[i]<hi))return null;const k=s.keys[i++],v=node(k);t=put(t,k);add('Consume preorder key '+k+' inside its allowed interval.','A token outside this slot is left for the next ancestor slot.',{active:[k],lines:['Consumed tokens: '+i,'Allowed lower: '+(Number.isFinite(lo)?lo:'unbounded'),'Allowed upper: '+(Number.isFinite(hi)?hi:'unbounded')]});v.left=parse(lo,k);v.right=parse(k,hi);return v;};t=parse(-Infinity,Infinity);result={valid:i===s.keys.length,consumed:i,preorder:list(t,'preorder'),postorder:list(t,'postorder')};if(i!==s.keys.length)add('Reject the unconsumed preorder suffix.','Construction of a prefix alone is not full validation.',{bad:true,lines:['First unconsumed key: '+s.keys[i],'Valid preorder: false']});}
else if(['rank','select'].includes(s.operation)){let v=t,acc=0,j=s.q;while(v){const l=size(v.left);add(s.operation==='rank'?'Count the entire discarded rank block at '+v.key+'.':'Compare residual rank '+j+' with left size '+l+'.','Stored subtree sizes identify complete consecutive key blocks.',{active:[v.key],lines:s.operation==='rank'?['Query key: '+s.q,'Left subtree size: '+l,'Accumulated strict rank: '+acc]:['Residual rank: '+j,'Left subtree size: '+l,'Use zero-based selection.']});if(s.operation==='rank'){if(s.q<=v.key){if(s.q===v.key){acc+=l;break;}v=v.left;}else{acc+=l+1;v=v.right;}}else{if(j===l){result={selected:v.key};break;}if(j<l)v=v.left;else{j-=l+1;v=v.right;}}}if(s.operation==='rank')result={rank:acc};add('Return the exact ordered-query result.','Rank is strict; select is zero-based.',{lines:[JSON.stringify(result)]});}
else if(s.operation==='range'){const out=[];const walk=v=>{if(!v)return;add('Inspect key '+v.key+' and prune impossible subtrees.','A lower or upper endpoint excludes an entire ordered block.',{active:[v.key],emitted:copy(out),lines:['Inclusive interval: '+s.a+' to '+s.b,'Go left: '+(s.a<v.key),'Emit: '+(s.a<=v.key&&v.key<=s.b),'Go right: '+(v.key<s.b)]});if(s.a<v.key)walk(v.left);if(s.a<=v.key&&v.key<=s.b)out.push(v.key);if(v.key<s.b)walk(v.right);};walk(t);add('Finish the sorted interval output.','Boundary routes and emitted keys account for the work.',{emitted:out,lines:['Count: '+out.length,'Only declared endpoints are inclusive.']});result={keys:out,count:out.length};}
else if(s.operation==='multiplicity'){if(s.keys.length!==3)throw Error('Counted example uses three distinct nodes.');const sorted=list(t);for(let i=0;i<3;i++)find(t,sorted[i]).count=[2,3,1][i];let total=0;for(const k of sorted){const c=find(t,k).count;add('Assign a complete occurrence-rank block to key '+k+'.','One strict node can own several consecutive occurrence ranks.',{active:[k],lines:['Count: '+c,'Ranks: '+total+' through '+(total+c-1),'Total mass: '+mass(t)]});total+=c;}result={mass:mass(t),expanded:sorted.flatMap(k=>Array(find(t,k).count).fill(k))};}
else if(s.operation==='cost'){const r=stats(t);let total=0;const walk=(v,d)=>{if(!v)return;total+=d;add('Add depth '+d+' for key '+v.key+'.','Internal path length sums actual depths; successful cost adds one per key.',{active:[v.key],lines:['Node depth: '+d,'Partial internal sum: '+total,'Successful node cost: '+(d+1)]});walk(v.left,d+1);walk(v.right,d+1);};walk(t,0);result={...r,successfulNumerator:r.I+r.n,successfulDenominator:r.n,failedNumerator:r.E,failedDenominator:r.n+1};add('Apply E = I + 2n and the declared uniform query models.','Actual-node and null-gap distributions have different normalizations.',{lines:['I: '+r.I+'; E: '+r.E,'Successful mean: '+(r.I+r.n)+' / '+r.n,'Uniform-gap mean: '+r.E+' / '+(r.n+1)]});}
else if(s.operation==='orders'){const target=JSON.stringify(label(t)),rows=permutations([...s.keys].sort((a,b)=>a-b)).filter(a=>JSON.stringify(label(build(a)))===target);for(let i=0;i<rows.length;i++)add('Inspect producing permutation '+(i+1)+'.','Every ancestor precedes its descendants; left/right sequences can interleave.',{sequence:rows[i],lines:['Producing order: '+(i+1)+' of '+rows.length,'The fixed tree is unchanged.']});result={count:rows.length,orders:rows};}
else if(s.operation==='rotation'){if(!t.right)throw Error('Left rotation requires a right child.');add('Identify x, its right child y, and the middle subtree B.','The inorder blocks are A, x, B, y, C.',{active:[t.key,t.right.key],lines:['Old root x: '+t.key,'Right child y: '+t.right.key,'Middle subtree: '+(t.right.left?.key??'null')]});const x=t,y=t.right;x.right=y.left;y.left=x;t=y;add('Reconnect B under x, then x under y and the outer root to y.','The sorted key sequence is unchanged; refresh lower metadata before upper.',{active:[x.key,y.key],lines:['New root: '+y.key,'Lower subtree size: '+size(x),'Upper subtree size: '+size(y)]});result={inorder:list(t),preorder:list(t,'preorder')};}
else if(s.operation==='random'){const orders=permutations([...s.keys].sort((a,b)=>a-b));const bins={};let I=0,H=0;for(const a of orders){t=build(a);const key=JSON.stringify(shape(t));bins[key]=(bins[key]||0)+1;I+=stats(t).I;H+=height(t);add('Build the next equally likely insertion permutation.','Equal permutation probabilities do not make resulting shapes equiprobable.',{sequence:a,lines:['Permutation: '+a.join(', '),'Edge height: '+height(t),'Internal sum: '+stats(t).I],bins:copy(bins)});}result={orders:orders.length,shapeMultiplicities:Object.values(bins).sort(),heightNumerator:H,internalNumerator:I,denominator:orders.length};}
return{spec:s,states,result};}
function svg(s,z){const all=[...new Set(s.keys.concat(list(z.tree)))].sort((a,b)=>a-b),positions={},nodes=[],gap=Math.min(65,250/Math.max(1,height(z.tree)));function walk(t,d){if(!t)return;positions[t.key]={x:40+(all.indexOf(t.key)+.5)*510/all.length,y:60+d*gap};nodes.push(t);walk(t.left,d+1);walk(t.right,d+1);}walk(z.tree,0);const max=nodes.length?Math.max(...nodes.map(n=>positions[n.key].y)):60;const H=Math.max(350,max+90);let b='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 '+H+'" role="img" aria-label="'+esc(s.operation)+' exact tree checkpoint"><defs><marker id="bt-arrow" viewBox="0 0 8 8" refX="8" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#617b89"/></marker></defs><rect x="6" y="6" width="748" height="'+(H-12)+'" rx="14" fill="#f5f8f9"/>';
for(const n of nodes){const p=positions[n.key];for(const child of[n.left,n.right])if(child){const c=positions[child.key],dy=c.y-p.y,dx=c.x-p.x,len=Math.hypot(dx,dy),sx=p.x+dx/len*25,sy=p.y+dy/len*25,ex=c.x-dx/len*25,ey=c.y-dy/len*25,mid=(sy+ey)/2;b+='<path data-edge="'+n.key+':'+child.key+'" d="M'+sx+' '+sy+' L'+ex+' '+ey+'" fill="none" stroke="#617b89" stroke-width="1.7" marker-end="url(#bt-arrow)"/>';}}
for(const n of nodes){const p=positions[n.key],active=z.active.includes(n.key),fill=active?(z.bad?'#f9d9d5':'#d7ecea'):'#ffffff';b+='<g data-entity="bst-entry-'+n.key+'" data-key="'+n.key+'"><circle cx="'+p.x+'" cy="'+p.y+'" r="25" fill="'+fill+'" stroke="'+(active?'#287972':'#9aafb9')+'"/><text x="'+p.x+'" y="'+(p.y+6)+'" text-anchor="middle" class="bt-math">'+n.key+'</text></g>';if(s.operation==='rank'||s.operation==='select'||s.operation==='multiplicity')b+='<text x="'+p.x+'" y="'+(p.y+43)+'" text-anchor="middle" class="bt-meta">'+(s.operation==='multiplicity'?'c='+n.count:'s='+size(n))+'</text>';}
if(!nodes.length)b+='<text x="260" y="100" text-anchor="middle" class="bt-prose">Empty dictionary</text>';
b+='<path d="M575 24 V'+(H-24)+'" stroke="#c9d7dc"/><text x="596" y="44" class="bt-prose">Exact checkpoint</text>';
let y=82;for(const raw of z.lines||[]){const words=raw.split(' ');let line='';for(const w of words){if((line+' '+w).length>19){b+='<text x="596" y="'+y+'" class="bt-prose">'+esc(line)+'</text>';y+=23;line=w;}else line+=(line?' ':'')+w;}if(line){b+='<text x="596" y="'+y+'" class="bt-prose">'+esc(line)+'</text>';y+=23;}y+=12;}
const seq=z.sequence||z.emitted;if(seq?.length){const x0=30,w=500/Math.max(seq.length,1),by=H-55;for(let i=0;i<seq.length;i++)b+='<rect x="'+(x0+i*w)+'" y="'+by+'" width="'+(w-7)+'" height="42" rx="6" fill="#e3eeef"/><text x="'+(x0+i*w+(w-7)/2)+'" y="'+(by+27)+'" text-anchor="middle" class="bt-math">'+seq[i]+'</text>';}
return b+'</svg>';}
function makeModel(id,title,raw){const{spec:s,states,result}=evaluate(raw);return{id,title,kind:'exact-discrete',spec:s,result,invariant:'Each checkpoint declares the exact child links, query and order or metadata condition; playback begins paused.',frames:states.map((z,i)=>({svg:svg(s,z),caption:'Checkpoint '+(i+1)+' of '+states.length,formula:'',formulaHtml:'<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>n</mi><mo>=</mo><mn>'+size(z.tree)+'</mn><mo>,</mo><mi>h</mi><mo>=</mo><mn>'+height(z.tree)+'</mn></mrow></math>',snapshot:{step:i+1,state:copy(z),inputs:s,result:i===states.length-1?result:null},teaching:{currentState:title+', checkpoint '+(i+1),operation:z.action,why:z.why,reading:'Follow connected parent-to-child arrows. The highlighted nodes participate in the declared operation; the side panel states exact decisions.',checks:[{mathHtml:'Actual reachable nodes',result:String(size(z.tree))},{mathHtml:'Global strict order',result:String(valid(z.tree))}]}}))};}
if(typeof module!=='undefined')module.exports={validate,evaluate,makeModel,build,put,erase,list,size,mass,height,valid,stats,permutations,label};
if(typeof document==='undefined')return;
function followPorts(host){const sync=()=>{for(const svg of host.querySelectorAll('svg')){const inverse=svg.getCTM()?.inverse();if(!inverse)continue;for(const e of svg.querySelectorAll('[data-edge]')){const keys=e.dataset.edge.split(':'),a=svg.querySelector('[data-key="'+keys[0]+'"] circle'),b=svg.querySelector('[data-key="'+keys[1]+'"] circle');if(!a||!b)continue;const center=c=>new DOMPoint(c.cx.baseVal.value,c.cy.baseVal.value).matrixTransform(c.getCTM()).matrixTransform(inverse),p=center(a),q=center(b),dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy);if(len<1)continue;const ar=a.r.baseVal.value,br=b.r.baseVal.value;e.setAttribute('d','M'+(p.x+dx/len*ar)+' '+(p.y+dy/len*ar)+' L'+(q.x-dx/len*br)+' '+(q.y-dy/len*br));}}};const observer=new MutationObserver(sync);observer.observe(host,{childList:true,subtree:true,attributes:true,attributeFilter:['cx','cy','transform']});sync();return()=>observer.disconnect();}
function mount(host,m){if(!host.querySelector('.bt-controls')){const c=document.createElement('div');c.className='bt-controls';c.innerHTML='<button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.bt-stage').before(c);}for(const cls of['bt-caption','bt-formula','bt-print'])if(!host.querySelector('.'+cls)){const e=document.createElement('div');e.className=cls;host.append(e);}const p=AdvancedSimulations.mount(host,m,{topic:'a_bst',prefix:'bt',retainDrawing:true}),stop=followPorts(host),dispose=p.dispose;p.dispose=()=>{stop();dispose();};return p;}
async function boot(){const data=await(await fetch('a_bst-models.json')).json();globalThis.BSTPlayers=[];for(const host of document.querySelectorAll('[data-bt-model]')){const m=data.models.find(m=>m.id===host.dataset.btModel);if(!m)throw Error('Missing declared BST model');BSTPlayers.push(mount(host,m));}let active;const f=document.querySelector('#bt-form'),out=document.querySelector('#bt-output'),error=document.querySelector('#bt-error');f.addEventListener('submit',ev=>{ev.preventDefault();try{const raw={operation:f.elements.operation.value,keys:f.elements.keys.value.split(',').map(x=>Number(x.trim())),q:Number(f.elements.q.value),a:Number(f.elements.a.value),b:Number(f.elements.b.value)};if(f.elements.keys.value.split(',').some(x=>!x.trim()))throw Error('Every comma-separated key must be present.');const m=makeModel('editable-bst','Your exact BST trace',raw);active?.dispose();out.innerHTML='<section class="bt-model"><h3>'+esc(m.title)+'</h3><div class="bt-stage"></div></section><h3>Exact result</h3><pre>'+esc(JSON.stringify(m.result,null,2))+'</pre>';active=mount(out.firstChild,m);globalThis.BSTLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});f.dispatchEvent(new Event('submit',{cancelable:true}));}boot().catch(e=>{document.querySelector('#bt-error').textContent=e.message;throw e;});
})();
